import json, math, re, pathlib
from collections import defaultdict, Counter

# 1. "Crawl": read every blog post on this site (title and description)
docs = {}
for f in sorted(pathlib.Path("content/blog/data").glob("*.json")):
    meta = json.loads(f.read_text(encoding="utf-8"))["meta"]
    docs[meta["slug"]] = meta["title"] + " " + meta["description"]

STOP = {"a", "an", "and", "the", "of", "to", "in", "for", "on", "with", "is", "how", "what", "your", "you", "it", "from", "by", "or", "are", "at"}
def words(text):
    return [w for w in re.findall(r"[a-z0-9]+", text.lower()) if w not in STOP]

# 2. Index: for every word, which documents contain it, and how often
index = defaultdict(dict)
for slug, text in docs.items():
    for word, count in Counter(words(text)).items():
        index[word][slug] = count
print(f"indexed {len(docs)} posts, {len(index):,} distinct words")
print("posts containing 'fractions':", len(index["fractions"]))
print("posts containing 'python':   ", len(index["python"]))

# 3. Rank: TF-IDF, so rare words count for more than common ones
def search(query, top=3):
    scores = Counter()
    for word in words(query):
        postings = index.get(word, {})
        if not postings:
            continue
        idf = math.log(len(docs) / len(postings))
        for slug, tf in postings.items():
            scores[slug] += tf * idf
    return scores.most_common(top)

for w in words("fractions for children"):
    print(f"idf of {w!r}: log({len(docs)} / {len(index[w])}) = {math.log(len(docs) / len(index[w])):.2f}")

for q in ["fractions for children", "python projects beginners", "olympiad proof"]:
    print(f"\nsearch: {q!r}")
    for slug, score in search(q):
        print(f"  {score:5.2f}  {slug}")

import json, re, pathlib

# Build the link graph: which blog posts link to which other blog posts
posts, links = {}, {}
for f in sorted(pathlib.Path("content/blog/data").glob("*.json")):
    data = json.loads(f.read_text(encoding="utf-8"))
    slug = data["meta"]["slug"]
    posts[slug] = data["meta"]["title"]
    text = json.dumps(data["content"]["sections"])
    links[slug] = set(re.findall(r"/blog/([a-z0-9-]+)", text))
for slug in links:
    links[slug] = {t for t in links[slug] if t in posts and t != slug}

# PageRank: a page is important if important pages link to it
n, d = len(posts), 0.85
rank = {s: 1 / n for s in posts}
for _ in range(50):
    new = {s: (1 - d) / n for s in posts}
    for s, outs in links.items():
        if outs:
            share = d * rank[s] / len(outs)
            for t in outs:
                new[t] += share
        else:                                  # a page with no links shares evenly
            for t in posts:
                new[t] += d * rank[s] / n
    rank = new

inbound = {s: sum(s in outs for outs in links.values()) for s in posts}
total_links = sum(len(o) for o in links.values())
print(f"{n} posts, {total_links:,} internal links between them")
print("top 5 by PageRank:")
for s in sorted(rank, key=rank.get, reverse=True)[:5]:
    print(f"  {rank[s] * 1000:5.2f}  {inbound[s]:>3} inbound  {s}")
